var S=[[0],[1,2],[3,4],[5,6],[7,8]];
var bk=document.getElementById("book"),ct=document.getElementById("ct"),pv=document.getElementById("pv"),nx=document.getElementById("nx");
var mq=window.matchMedia("(max-width:820px)"),i=0,busy=false;
function units(){return mq.matches?P.map(function(_,k){return [k]}):S}
function draw(){var U=units();if(i>=U.length)i=U.length-1;
var h=U[i].map(function(k){return P[k]}).join("");
if(!mq.matches&&U[i].length==1)h+='<div class="page l dark"></div>';
bk.innerHTML=h;ct.textContent=(i+1)+" / "+U.length;nx.disabled=i>=U.length-1;pv.disabled=i<=0}
function go(d){var U=units(),n=i+d;if(busy||n<0||n>=U.length)return;busy=true;
bk.className="book "+(d>0?"t-next":"t-prev");
setTimeout(function(){i=n;draw();bk.className="book t-"+(d>0?"prev":"next");void bk.offsetWidth;bk.className="book";setTimeout(function(){busy=false},280)},280)}
nx.onclick=function(){go(1)};pv.onclick=function(){go(-1)};
document.addEventListener("keydown",function(e){if(e.key=="ArrowLeft")go(1);if(e.key=="ArrowRight")go(-1)});
bk.addEventListener("click",function(e){if(e.target.closest("a"))return;var r=bk.getBoundingClientRect();go(e.clientX<r.left+r.width/2?1:-1)});
var sx=null;bk.addEventListener("touchstart",function(e){sx=e.touches[0].clientX},{passive:true});
bk.addEventListener("touchend",function(e){if(sx===null)return;var dx=e.changedTouches[0].clientX-sx;if(Math.abs(dx)>50)go(dx<0?1:-1);sx=null});
mq.addEventListener("change",function(){i=0;draw()});
draw();
